fn is_sorted(arr: &Vec<i32>) -> bool {
    // Requires: arr is a non-empty vector
    // Ensures: returns true if arr is sorted in non-decreasing order, false otherwise
    // Invariant: For all indices i in the range 0..(arr.len() - 1), arr[i] <= arr[i + 1]
    // Decreases: arr.len()
    assert!(arr.len() > 0); // Ensure the array is non-empty

    let n = arr.len();
    let mut i = 0;

    // Loop invariant: 0 <= i <= n - 1 and for all j in 0..i, arr[j] <= arr[j + 1]
    while i < n - 1 {
        // Check the loop invariant
        assert!(i < n - 1);
        assert!(arr[i] <= arr[i + 1] || i == n - 2); // Ensure the current pair is in order or we are at the last comparison

        if arr[i] > arr[i + 1] {
            return false; // If any element is greater than the next, return false
        }
        i += 1; // Move to the next index
    }
    true // If we complete the loop without finding any issues, return true
}

fn main() {
    let arr1 = vec![1, 2, 2, 3, 4];
    let arr2 = vec![1, 3, 2, 4];
    
    println!("{}", is_sorted(&arr1)); // Should print true
    println!("{}", is_sorted(&arr2)); // Should print false
}